#page-title,
.meta-title {
    display: none;
}

/* ==========================================================================
   Conteneur principal
   ========================================================================== */
.anom-bar-container,
.anom-bar-container * {
    box-sizing: border-box;
    padding: 0;
    margin: 0;
    font-family: var(--font-text, Inter, sans-serif);
}

.anom-bar-container {
    width: 100%;
    display: flex;
    position: relative;
}

hr + .anom-bar-container,
.anom-bar-container:not(:first-child) {
    padding-top: 1em;
}

.anom-bar {
    display: grid;
    grid-template-areas:
        "top-box"
        "bottom-box";
    width: 100%;
}

/* ==========================================================================
   Barre supérieure (Item, Barres, Level/Clearance)
   ========================================================================== */
.anom-bar > .top-box {
    grid-area: top-box;
    display: grid !important;
    grid-template-columns: auto 1fr auto !important;
    grid-template-areas: "top-left-box top-center-box top-right-box" !important;
    align-items: center !important;
    gap: 1.5rem !important;
    padding-bottom: 1rem !important;
    font-weight: 600;
    text-transform: uppercase;
    height: auto !important;
}

.top-box .top-left-box {
    grid-area: top-left-box;
}

.top-left-box > .item {
    font-size: calc(12px + 8 * ((100vw - 300px) / 960));
}

.top-left-box > .number {
    font-size: calc(25px + 25 * ((100vw - 300px) / 1620));
}

.top-box .top-center-box {
    grid-area: top-center-box;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    margin: 0 1rem;
}

.top-center-box > div {
    background-color: rgb(0, 0, 0);
    height: 0.5rem;
    width: 100%;
    margin: 0.125rem 0;
    display: none;
}

.anom-bar-container.clear-1 .top-center-box > div { background-color: rgb(var(--one-color)); }
.anom-bar-container.clear-2 .top-center-box > div { background-color: rgb(var(--two-color)); }
.anom-bar-container.clear-3 .top-center-box > div { background-color: rgb(var(--three-color)); }
.anom-bar-container.clear-4 .top-center-box > div { background-color: rgb(var(--four-color)); }
.anom-bar-container.clear-5 .top-center-box > div { background-color: rgb(var(--five-color)); }
.anom-bar-container.clear-6 .top-center-box > div {
    background-color: rgb(var(--swatch-primary, 133, 0, 5));
    background-image: url("data:image/jpeg;base64,");
    background-attachment: fixed;
    background-size: contain;
    background-blend-mode: overlay;
}

