   ========================================================================== */
.anom-bar > .bottom-box {
    grid-area: bottom-box;
    display: grid;
    grid-template-areas: "text-part diamond-part";
    grid-template-columns: 1fr 6rem;
    gap: 0.5rem;
    width: 100%;
    height: 6rem;
    font-weight: 600;
    box-shadow: 0 -0.5rem 0 0 rgb(var(--swatch-menubg-black-color, 12, 12, 12));
    margin-top: -0.5rem;
    padding-top: 0.25rem;
}

.bottom-box > .text-part {
    grid-area: text-part;
    display: grid;
    grid-template-areas:
        "main-class disrupt-class"
        "main-class risk-class";
    grid-template-rows: 1fr 1fr;
    grid-template-columns: 3fr 2fr;
    gap: 0.25rem;
    height: 6rem;
    text-transform: uppercase;
}

.text-part div {
    padding: 0 0.125rem;
    margin-left: 0.25rem;
    position: relative;
}

.text-part > .main-class {
    grid-area: main-class;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    border-width: 1em !important;
}

.anom-bar-container:not(.esoteric) .text-part > .main-class { padding-right: 3.5rem; }
.anom-bar-container.esoteric .text-part > .main-class { padding-right: 2rem; }

.text-part > .main-class::before {
    content: "";
    position: absolute;
    top: calc(50% - 2.25rem);
    right: 0.5rem;
    width: 3.53125rem;
    height: 3.53125rem;
    border-radius: 50%;
    border: 0.25rem solid rgb(var(--swatch-menutxt-dark-color, 12, 12, 12));
    background-color: rgb(var(--swatch-background, 252, 252, 252));
    background-size: 110% 110%;
    background-position: center;
    background-repeat: no-repeat;
}

/* 1. Force la capsule gauche sur fond noir avec l'icône Esoteric à la bonne taille */
.anom-bar-container.esoteric .text-part > .main-class::before {
    top: 0.5rem !important;
    right: 0.25rem !important; /* On ancre la capsule à droite */
    width: 6.5rem !important; /* Capsule plus longue pour faire un bel ovale */
    border-radius: calc(3.53125rem / 2) !important;
    background-color: #0c0c0c !important;
    border: 0.25rem solid #0c0c0c !important;
    background-image: var(--icon-esoteric) !important;
    background-size: 3rem !important; /* Taille fixe pour éviter que l'icône soit écrasée */
    background-repeat: no-repeat !important;
    background-position: left 0.1rem center !important; /* Centré proprement à gauche */
    filter: none !important;
    display: block !important;
    z-index: 1 !important;
}

/* 2. Pastille blanche droite : icône secondaire (Thaumiel) agrandie */
.anom-bar-container.esoteric .text-part > .main-class::after {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    top: 0.5rem !important;
    right: 0.25rem !important;
    width: 3.53125rem !important;
    height: 3.53125rem !important;
    border-radius: 50% !important;
    border: 0.25rem solid #0c0c0c !important;
    background-color: rgb(var(--swatch-background, 252, 252, 252)) !important;
    background-size: 100% 100% !important; /* Ajusté à la taille des autres icônes */
    background-position: center !important;
    background-repeat: no-repeat !important;
    z-index: 2 !important;
}

/* 3. Force le cadran supérieur du losange à 110% pour l'icône Esoteric */
.anom-bar-container.esoteric .danger-diamond > .top-icon::before {
    background-color: #0c0c0c !important;
    background-image: var(--icon-esoteric) !important;
    background-size: 110% !important; /* Passe de 75% à 110% pour remplir le cadran */
    filter: none !important;
}

.anom-bar-container.explained .text-part > .main-class::before,
.anom-bar-container.pending .text-part > .main-class::before,
.anom-bar-container.neutralized .text-part > .main-class::before,
.anom-bar-container.decommissioned .text-part > .main-class::before {
    display: none;
}

/* Confinement - Icônes principales */
.anom-bar-container.safe .text-part > .main-class::before { background-color: rgb(var(--one-color)); background-image: var(--icon-safe); }
.anom-bar-container.euclid .text-part > .main-class::before { background-color: rgb(var(--three-color)); background-image: var(--icon-euclid); }
.anom-bar-container.keter .text-part > .main-class::before { background-color: rgb(var(--five-color)); background-image: var(--icon-keter); }
.anom-bar-container.thaumiel .text-part > .main-class::before { background-color: rgb(var(--thaumiel-color)); background-image: var(--icon-thaumiel); }
.anom-bar-container.apollyon .text-part > .main-class::before { background-color: rgb(var(--apollyon-color)); background-image: var(--icon-apollyon); }
.anom-bar-container.archon .text-part > .main-class::before { background-color: rgb(var(--archon-color)); background-image: var(--icon-archon); }

/* Confinement - Icônes ésotériques secondaires */
.anom-bar-container.thaumiel.esoteric .text-part > .main-class::after { background-image: var(--icon-thaumiel); }
.anom-bar-container.apollyon.esoteric .text-part > .main-class::after { background-image: var(--icon-apollyon); }
.anom-bar-container.archon.esoteric .text-part > .main-class::after { background-image: var(--icon-archon); }

.text-part > .main-class > div {
    width: 100%;
    display: flex;
}

.anom-bar-container.esoteric .text-part > .main-class > .second-class > .class-text {
    font-size: calc(6px + 5 * ((100vw - 400px) / 400));
}

.anom-bar-container:not(.esoteric) .text-part > .main-class > .contain-class > .class-text {
    font-size: calc(10px + 8 * ((100vw - 400px) / 400));
}

.anom-bar-container:not(.esoteric) .text-part > .main-class > .second-class {
    display: none;
}

.text-part > .disrupt-class { grid-area: disrupt-class; overflow: hidden; }
.text-part > .risk-class { grid-area: risk-class; overflow: hidden; }

/* Couleurs des fonds et bordures latérales */
